#!/usr/bin/env python3
"""Copy completed saved audits and prove replay of one explicit staged raw archive."""
import argparse,pathlib,shutil,subprocess,json,copy,hashlib,datetime
p=argparse.ArgumentParser();p.add_argument('label');a=p.parse_args();label=a.label
assert label in {'observed-ui-hour','observed-none-hour','observed-audio-hour'}
base=pathlib.Path('benchmarks-local/isolation-2026-10-16');out=base/'staged-archive'/label
assert (out/'raw-manifest.json').is_file() and not (out/'derived-manifest.json').exists()
owned={}
def digest(raw):return hashlib.sha256(raw).hexdigest()
def add(source,name):
    raw=source.read_bytes();assert not (out/name).exists();shutil.copyfile(source,out/name);owned[name]={'source':str(source),'bytes':len(raw),'sha256':digest(raw)}
def generated(name,source):
    raw=(out/name).read_bytes();owned[name]={'source':source,'bytes':len(raw),'sha256':digest(raw)}
for source,name in [('resume-audit.py','resume-audit.py'),(f'{label}-independent-audit.json','independent-audit.json'),('thermal-snapshot-audit.py','thermal-snapshot-audit.py'),(f'{label}-thermal-snapshot-audit.json','thermal-snapshot-audit.json'),('resume-audit-verification.json','resume-audit-verification.json'),('thermal-snapshot-audit-verification.json','thermal-snapshot-audit-verification.json')]:add(base/source,name)
if label=='observed-none-hour':add(base/'observed-both-ui-none-reference-comparison.json','reference-comparison-both-ui-none.json')
command=['/bin/python3','-B',str(out/'resume-audit.py'),'--run-directory',str(out),'--source-snapshot',str(out/'stem_soak-executed-v3.py'),'--output',str(out/'archived-resume-audit.json')]
run=subprocess.run(command,capture_output=True,text=True,timeout=30);assert run.returncode==0,(run.stdout,run.stderr)
original=json.loads((out/'independent-audit.json').read_text());replay=json.loads((out/'archived-resume-audit.json').read_text())
a,b=copy.deepcopy(original),copy.deepcopy(replay);ignored=[]
for parent,key in [('source_snapshot_verified','path'),('source_evidence','events_stored_path'),('source_evidence','events_stored_sha256')]:
    ignored.append({'parent':parent,'key':key,'raw_audit_value':a[parent].pop(key),'archived_replay_value':b[parent].pop(key)})
assert a==b,[(k,a[k],b[k]) for k in a if a[k]!=b[k]]
generated('archived-resume-audit.json','generated by replay command in archived-replay-verification.json')
verification={'schema':1,'scope':'CPU-only replay of staged deterministic gzip raw evidence, archive metadata fallback and pinned staged soak source. No host query or benchmark workload.','command':command,'returncode':run.returncode,'stdout':run.stdout,'stderr':run.stderr,'semantic_facts_equal':True,'intentional_representation_differences':ignored,'raw_manifest_unchanged':True}
(out/'archived-replay-verification.json').write_text(json.dumps(verification,indent=2)+'\n');generated('archived-replay-verification.json','generated file-only semantic comparison')
manifest={'schema':1,'scope':'Derived audit files only; disjoint from raw-manifest.json ownership. Helper verification includes baseline cases as helper evidence; baseline archive was not changed.','created_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':owned,'raw_manifest_sha256':digest((out/'raw-manifest.json').read_bytes()),'archive_helper_sha256':digest(pathlib.Path(__file__).read_bytes())}
(out/'derived-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
for name,entry in owned.items():
    raw=(out/name).read_bytes();assert len(raw)==entry['bytes'] and digest(raw)==entry['sha256']
print(json.dumps({'label':label,'derived_files':len(owned),'derived_manifest_sha256':digest((out/'derived-manifest.json').read_bytes()),'raw_manifest_sha256':manifest['raw_manifest_sha256'],'semantic_facts_equal':True},indent=2))
